use crate::wasi::clocks::wall_clock;

struct Node;

/// Last second of 9999-12-31 (UTC). Clamping to this keeps the rendered
/// date at exactly ten characters (`YYYY-MM-DD`) whatever the clock says.
const MAX_DATE_SECONDS: u64 = 253_402_300_799;

/// Convert days since 1970-01-01 to a (year, month, day) civil date in the
/// proleptic Gregorian calendar.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + if month <= 2 { 1 } else { 0 };
    (year, month, day)
}

fn format_date(seconds: u64) -> String {
    let clamped = if seconds > MAX_DATE_SECONDS {
        MAX_DATE_SECONDS
    } else {
        seconds
    };
    let (year, month, day) = civil_from_days(clamped / 86_400);
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
```

I left out the `aap:caps/http-client@0.1.0` import and the enrichment fetch. The node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`, and until the graph definition itself changes, an extra import would exceed that grant and send the tick's text to an outside host. Once the grant is updated in the graph, adding the fetch is a small change, and the output stays the same either way.

